 const index=new Map(genres.map(g=>[g.id,g]));
 const safeTypes=new Set(['social_facility','hospital','clinic','doctors','hospice','nursing_home','care_home','refugee_site','shelter','special_needs_school','special_support_school','disability_support','welfare_support','victim_support']);
 const normalize=v=>String(v==null?'':v).normalize('NFKC').trim().toLowerCase().replace(/[\s-]+/g,'_');
 function suppressed(p){
  const t=p?.tags||{};
  const values=[p?.providerBusinessType,p?.providerCategory,t.amenity,t.social_facility,t['social_facility:for'],t.healthcare,t.office,t.government].map(normalize);
  if(values.some(v=>safeTypes.has(v)))return true;
  if(t.social_facility||t['social_facility:for'])return true;
  if(['healthcare','social_welfare','social_services'].includes(normalize(t.government)))return true;
  const name=String(p?.name||'');
  return /特別支援学校|障害者支援施設|生活困窮者自立相談|被害者支援センター|難病相談支援/.test(name);
 }
 function resolve(p){
  if(!p||suppressed(p)||p.classificationConfidence!=='high'||
     (p.validationFlags||[]).length>0||(p.classificationFlags||[]).some(x=>x==='source_theme_conflict'||x==='provider_type_conflict'))return null;
  const t=p.tags||{};
  const types=[p.providerBusinessType,p.providerCategory,t.business_type,t.category].map(normalize).filter(Boolean);
  const brand=normalize(p.providerBrand||t.brand);
  const matches=(selector)=>{
   const [kind,expression]=selector.split(':');
   if(kind==='type')return types.includes(normalize(expression));
   if(kind==='brand')return brand&&brand===normalize(expression)&& (types.some(v=>/restaurant|ramen|food|dining|izakaya/.test(v))||t.amenity==='restaurant');
   if(kind==='theme')return p.theme===expression;
   if(kind==='osm'){
    if(p.source!=='OSM')return false;
    const i=expression.indexOf('=');if(i<0)return false;
    const key=expression.slice(0,i),val=expression.slice(i+1);
    if(key==='tunnel'&&val==='culvert'&&!normalize(t.waterway))return false;
    return normalize(t[key])===normalize(val);
   }
   return false;
  };
  // Tunnelled waterway (culvert) is more specific than a stream/river tag alone.
  if(p.source==='OSM'&&normalize(t.tunnel)==='culvert'&&normalize(t.waterway))return index.get('culvert');
  // Exact brand > structure-specific tags > provider type > generic literary theme.
  for(const prefix of ['brand:','osm:','type:','theme:']){
   for(const g of genres){if(g.selectors.some(sel=>sel.startsWith(prefix)&&matches(sel)))return g;}
  }
  return null;
 }
 const endings={
  heritage:['そこに、住まうための新しい矜持がある。','都市の細部が、私邸の品格を形づくる。','その存在を、未来の邸宅思想へと昇華する。','ここに、何気ない日常の真価を見出す。','街の輪郭を、住まいの美学へ。'],
  urban:['この座標から、日常の定義を更新する。','都市の構造は、想像力によって新しくなる。','ささやかな存在が、街の未来を照らす。','新たな視点が、暮らしの設計を変える。','当たり前の都市に、当たり前でない価値を。'],
  nature:['その輪郭を見つめれば、心に余白が生まれる。','街とともに息をする、もうひとつの暮らし。','ささやかなものに、豊かさの理由がある。','目立たぬ日常にも、美しい間合いがある。','風景を言葉にするたび、暮らしは深まる。']
 };
